before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
#include <mutex>
#include <thread>
int main() {
    int count = 0;
    std::mutex mutex;
    auto work = [&] {
        for (int i = 0; i < 100; ++i) {
            std::lock_guard<std::mutex> lock(mutex);
            ++count;
        }
    };
    {
        std::jthread first(work);
        std::jthread second(work);
    }
    {
        std::lock_guard<std::mutex> finalLock(mutex);
        std::cout << count << "\n";
    }
}
```

